    if(dialog.querySelector('[data-v657-product]'))dialog.querySelector('[data-v657-product]').onchange=rerender;
    dialog.querySelectorAll('input,select').forEach(el=>{
      el.addEventListener('input',()=>{capture();preview();});
    });
