  if(sessions>0)chips.push(`<span class="customer-programme-holding"><b>${sessions}</b> ${esc(sessions===1?'session left':'sessions left')}</span>`);
  return chips.length?`<div class="customer-programme-holdings">${chips.join('')}</div>`:'';
