    button.disabled=true;button.textContent='Creating fixed snapshot…';
    if(status)status.innerHTML='<p class="muted small" style="margin-top:10px">Creating a fixed export snapshot so later activity cannot change pages while the file is prepared…</p>';
    const created=await sb.rpc('create_customer_intelligence_export_v83',lastRequest);
    if(!isCurrent()||!button.isConnected)return;
