        appointmentRows(scope.fromTs,scope.toExclusive,scope.branchId),
        appointmentRows(sgDateBoundary(scope.priorFrom),sgDateBoundary(scope.priorTo,1),scope.branchId),
        scheduledCapacityHours(scope)
