      const currentCadence=own?(ownSub?.cadence||'annual'):(b.terms?.cadence||selectedCadence);
      const chosen=own?(sheetCadenceV786||currentCadence):selectedCadence;
      /* nestly_v789 (owner: "now is just one pricing. monthly or yearly"): a firm that has not paid
         yet is priced at the flat tier like every branch; a firm already on a larger tier keeps the
         amount it pays until its next change. Capacity is never offered or mentioned. */
      const flatShared=!providerSubscription;
      const annualCents=own||flatShared?flatCentsV786('annual'):Number(tierForCapacityV664('annual',selectedCapacity)?.amount_cents||0);
      const monthlyCents=own||flatShared?flatCentsV786('monthly'):Number(tierForCapacityV664('monthly',selectedCapacity)?.amount_cents||0);
      const selectedTier=own?null:(selectedCadence==='annual'?tierForCapacityV664('annual',selectedCapacity):tierForCapacityV664('monthly',selectedCapacity));
      const unit=(own||flatShared)?(chosen==='annual'?annualCents:monthlyCents):(selectedTier?Number(selectedTier.amount_cents):0);
      const period=chosen==='annual'?'year':'month';
      const units=own?1:branchUnitsV664;
      const total=unit*units;
      const hasSub=own?!!ownSub?.provider_subscription_id&&['active','canceling','past_due','unpaid'].includes(String(ownSub.state||'')):providerSubscription;
      const life=own?billingLifecycleLinesV764(ownSub||{},ownSummaryFor(branch,ownSub),ownSub?.payment_method||null):lifecycleV764;
      const sameCad=own?(ownSub?.cadence===chosen):(b.terms?.cadence===selectedCadence);
      const sameCap=true;
      const ladder=[];
      const blockedReason=(own||flatShared)?(unit>0?'':'This billing cycle is not available for card checkout yet — contact Peekaa support.')
        :!selectedTier||selectedTier.checkout_available===false?'This plan is not available for card checkout yet — contact Peekaa support.':'';
      const primaryLabel=life.show_final?'Start a new plan':!hasSub?(own?'Pay for this branch':'Start secure checkout'):!sameCad?'Change billing cycle':!sameCap?'Increase capacity':'';
      const renewsAt=own?ownSub?.renews_at:summaryV758.renews_at;
